       }
       return s;
     }
     return { encode: encode, decode: decode };
   })();

   var B64 = (function () {
     var A = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
     function encode(bytes) {
