         out += A.charAt(b1 >> 2);
         out += A.charAt(((b1 & 3) << 4) | ((b2 === undefined ? 0 : b2) >> 4));
         out += b2 === undefined ? '=' : A.charAt(((b2 & 15) << 2) | ((b3 === undefined ? 0 : b3) >> 6));
