   };
   Buffer._decode = function (bytes, enc, start, end) {
     enc = String(enc || 'utf8').toLowerCase();
     start = start || 0;
     end = end === undefined ? bytes.length : end;
     if (enc === 'utf8' || enc === 'utf-8') { return UTF8.decode(bytes, start, end); }
     if (enc === 'ascii' || enc === 'latin1' || enc === 'binary') {
       var s = '';
